45: func legacyFixtureMigrationSQL(version int) ([]byte, error) {
46:     if version < 1 || version > len(legacyFixtureMigrationSources) {
47:         return nil, fmt.Errorf("legacy fixture migration version unavailable")
48:     }
49:     source := legacyFixtureMigrationSources[version-1]
50:     raw, err := os.ReadFile(filepath.Join("../../migrations/sqlite", source.filename))
51:     if err != nil { return nil, err }
52:     if Digest(raw) != source.digest {
53:         return nil, fmt.Errorf("legacy fixture migration source pin differs")
54:     }
55:     return raw, nil
56: }
