66: // The actual historical SQL and its version row commit in the same transaction.
67: // No hole is filled by relabelling a current database or recording unexecuted SQL.
68: func applyLegacyFixtureMigration(ctx context.Context, db *sql.DB, version int, raw []byte) (sql.Result, error) {
69:     if version < 2 || version > len(legacyFixtureMigrationSources) || Digest(raw) != legacyFixtureMigrationSources[version-1].digest {
70:         return nil, fmt.Errorf("legacy fixture migration source pin differs")
71:     }
72:     applied, err := checkMigrationInventory(db, legacyFixtureMigrationFiles())
73:     if err != nil { return nil, err }
74:     if applied != version-1 {
75:         return nil, fmt.Errorf("legacy fixture migration is not the next contiguous version")
76:     }
77:     tx, err := db.BeginTx(ctx, nil)
78:     if err != nil { return nil, err }
79:     defer tx.Rollback()
80:     result, err := tx.ExecContext(ctx, string(raw))
81:     if err != nil { return nil, err }
82:     if _, err = tx.ExecContext(ctx, "INSERT INTO schema_migrations(version) VALUES(?)", version); err != nil { return nil, err }
83:     if err = tx.Commit(); err != nil { return nil, err }
84:     return result, nil
85: }
86: 
87: func applyLegacyFixtureMigrationRange(ctx context.Context, db *sql.DB, first, last int) error {
88:     if first < 2 || first > last || last > len(legacyFixtureMigrationSources) {
89:         return fmt.Errorf("legacy fixture migration range unavailable")
90:     }
91:     for version := first; version <= last; version++ {
92:         raw, err := legacyFixtureMigrationSQL(version)
93:         if err != nil { return err }
94:         if _, err = applyLegacyFixtureMigration(ctx, db, version, raw); err != nil { return err }
95:     }
96:     return nil
97: }
