143: // Hash all schema definitions and public synthetic fixture table values to prove
144: // rejected New performs no additional DDL or data mutation. Values are never logged.
145: func legacyFixtureFingerprint(t *testing.T, db *sql.DB) string {
146:     t.Helper()
147:     rows, err := db.Query("SELECT type,name,tbl_name,sql FROM sqlite_master WHERE name NOT LIKE 'sqlite_%' ORDER BY type,name")
148:     if err != nil { t.Fatal(err) }
149:     var schema []any
150:     var tables []string
151:     for rows.Next() {
152:         var typ, name, table string
153:         var ddl sql.NullString
154:         if err = rows.Scan(&typ,&name,&table,&ddl); err != nil { rows.Close(); t.Fatal(err) }
155:         schema = append(schema, Object{"type":typ,"name":name,"table":table,"sql":ddl})
156:         if typ == "table" { tables = append(tables,name) }
157:     }
158:     err = rows.Err()
159:     rows.Close()
160:     if err != nil { t.Fatal(err) }
161:     data := Object{}
162:     for _, name := range tables {
163:         quoted := strings.ReplaceAll(name, "\"", "\"\"")
164:         records, e := db.Query("SELECT * FROM \""+quoted+"\"")
165:         if e != nil { t.Fatal(e) }
166:         columns, e := records.Columns()
167:         if e != nil { records.Close(); t.Fatal(e) }
168:         values := []any{}
169:         for records.Next() {
170:             row := make([]any,len(columns))
171:             refs := make([]any,len(columns))
172:             for i := range refs { refs[i] = &row[i] }
173:             if e = records.Scan(refs...); e != nil { records.Close(); t.Fatal(e) }
174:             values = append(values,row)
175:         }
176:         e = records.Err()
177:         records.Close()
178:         if e != nil { t.Fatal(e) }
179:         data[name] = Object{"columns":columns,"rows":values}
180:     }
181:     return Hash(Object{"schema":schema,"data":data})
182: }
